import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9fc8b2);
scene.fog = new THREE.Fog(0x9fc8b2, 78, 180);
const camera = new THREE.PerspectiveCamera(43, innerWidth / innerHeight, .1, 260);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.12;
document.body.prepend(renderer.domElement);

scene.add(new THREE.HemisphereLight(0xdff4ee, 0x385847, 2.15));
const sun = new THREE.DirectionalLight(0xfff3d9, 3.2); sun.position.set(-25, 55, 22); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048); sun.shadow.camera.left = -65; sun.shadow.camera.right = 65; sun.shadow.camera.top = 70; sun.shadow.camera.bottom = -70; sun.shadow.bias = -.00035; scene.add(sun);
const fill = new THREE.DirectionalLight(0xa4d5ff, 1.1); fill.position.set(24, 20, -40); scene.add(fill);
const mat = (color, roughness=.8, metalness=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const grass = mat(0x397d4a), stripeA = mat(0x43894f), stripeB = mat(0x397a47), white = mat(0xf1f1dc), blue = mat(0x164fce), blueBright = mat(0x3f79ff), red = mat(0xd84636), redBright = mat(0xff7451), skin = mat(0xc9895d), dark = mat(0x13231e), ballMat = mat(0xf5f2df,.48), black = mat(0x18211d,.4);
const field = new THREE.Group(); scene.add(field);
function box(parent, x,y,z, sx,sy,sz, material, cast=false, receive=false){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=receive;parent.add(m);return m;}
function sphere(parent,x,y,z,r,material,scale){const m=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),material);m.position.set(x,y,z);if(scale)m.scale.set(...scale);m.castShadow=true;parent.add(m);return m;}
function groundRect(x,z,w,d,material,y=.015){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,d),material);m.rotation.x=-Math.PI/2;m.position.set(x,y,z);m.receiveShadow=true;field.add(m);return m;}
// Stadium apron and striped, regulation-size pitch.
groundRect(0,0,180,180,mat(0x29443d),-.12); groundRect(0,0,70,100,grass,0);
for(let i=0;i<10;i++) groundRect(0,-45+i*10,70,10,i%2?stripeA:stripeB,.008);
// Touchlines and the painted football markings.
function line(x,z,w,d){groundRect(x,z,w,d,white,.025)}
line(0,-49.5,70,.22);line(0,49.5,70,.22);line(-34.9,0,.22,99);line(34.9,0,.22,99);line(0,0,69.8,.18);
const circle=new THREE.Mesh(new THREE.RingGeometry(9.85,10,.12,96),white);circle.rotation.x=-Math.PI/2;circle.position.y=.027;field.add(circle);
sphere(field,0,.03,0,.16,white);
for(const sign of [-1,1]){
  const z=sign*38.5; line(0,z,40, .18); line(-20,z-sign*5.5,.18,11); line(20,z-sign*5.5,.18,11); line(0,z-sign*11,40,.18);
  const goalZ=sign*44.5; line(0,goalZ,18,.18);line(-9,goalZ-sign*2.7,.18,5.5);line(9,goalZ-sign*2.7,.18,5.5);line(0,goalZ-sign*5.4,18,.18);
  const spot=sphere(field,0,.032,sign*32.5,.14,white); spot.scale.set(1,1,.65);
  const arc=new THREE.Mesh(new THREE.RingGeometry(9.8,10,.12,60,Math.PI*.14,Math.PI*.72),white);arc.rotation.x=-Math.PI/2;arc.position.set(0,.028,sign*32.5);field.add(arc);
}
// Goal frames, nets, and back net lines.
function makeGoal(z, dir){const g=new THREE.Group();field.add(g);const y=2.5, w=9;const post=mat(0xf6f5e8,.3);
  box(g,-w/2,y,z,w,.16,.16,post,true);box(g,-w/2,1.25,z,.16,2.5,.16,post,true);box(g,w/2,1.25,z,.16,2.5,.16,post,true);
  const back=z+dir*3.3;box(g,0,2.5,back,.08,.08,6.6,white);box(g,-w/2,1.25,(z+back)/2,.08,2.5,3.3,white);box(g,w/2,1.25,(z+back)/2,.08,2.5,3.3,white);
  for(let i=0;i<=12;i++){const x=-w/2+w*i/12;box(g,x,1.25,(z+back)/2,.025,2.5,3.3,mat(0xdde8dc,.9));}
  for(let i=0;i<=5;i++){const yy=i*.5;box(g,0,yy+.05,(z+back)/2,w,.025,3.3,mat(0xdde8dc,.9));}
}
makeGoal(-49,-1);makeGoal(49,1);
// Stadium bowl: charcoal retaining walls, colored seat bands, roof beams and floodlights.
const concrete=mat(0x34433e), upper=mat(0x20312c), seat1=mat(0x53675d), seat2=mat(0x7d8c71), accent=mat(0xd7ff51);
for(const side of [-1,1]){
  box(scene,side*40,5,0,2,10,110,concrete,false,true);
  for(let row=0;row<8;row++){
    const y=8+row*1.12, x=side*(39+row*.88);
    box(scene,x,y,0,1.6,.7,106, row%3===0?seat2:seat1);
    // Seat-color crowd dots give the stands a lively stadium texture.
    for(let n=0;n<115;n++){const zz=-50+n*.88;const dot=sphere(scene,x+side*(Math.random()*.55),y+.38+(Math.random()-.5)*.24,zz,.12,[mat(0xe4c89e),mat(0x3978a8),mat(0xc85542),mat(0xd5d4bd),mat(0x5d9c67)][Math.floor(Math.random()*5)]);dot.scale.set(.72,1.35,.72);}
  }
  box(scene,side*48,17,0,1.2,.35,112,upper);
  for(let z=-49;z<=49;z+=16){box(scene,side*48,19,z,1.5,4,.65,mat(0x374a42));box(scene,side*47.2,21,z,2.6,.22,5,mat(0xf4f3df,.25));}
}
for(const end of [-1,1]){
  box(scene,0,5,end*55,84,10,2,concrete,false,true);
  for(let row=0;row<7;row++)box(scene,0,8+row*1.15,end*(55+row*.75),82+row*1.2,.7,1.4,row%2?seat1:seat2);
  box(scene,0,17,end*61,90,.5,1.5,upper);
}
// Perimeter boards with vivid broadcast-style typography panels.
const boardMat=mat(0x102720,.35);for(const side of [-1,1]){box(scene,side*36,.7,0,.35,1.4,98,boardMat);for(let z=-43;z<47;z+=12)box(scene,side*35.78,.74,z,.08,.82,10,mat(z%24?0xbee847:0x66cbd0,.45));}
for(const z of [-50.5,50.5])box(scene,0,.7,z,68,1.4,.35,boardMat);

function makePlayer(team,x,z,number,keeper=false){
  const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
  const shirt=team==='home'?blue:red, detail=team==='home'?blueBright:redBright;
  const body=new THREE.Group();g.add(body);
  const torso=new THREE.Mesh(new THREE.CylinderGeometry(.42,.5,.95,12),shirt);torso.position.y=1.35;torso.castShadow=true;body.add(torso);
  const bib=new THREE.Mesh(new THREE.BoxGeometry(.08,.58,.035),mat(team==='home'?0xbcd8ff:0xffd0ac));bib.position.set(0,1.38,-.426);body.add(bib);
  const shorts=new THREE.Mesh(new THREE.CylinderGeometry(.48,.43,.42,12),dark);shorts.position.y=.67;shorts.castShadow=true;g.add(shorts);
  const head=sphere(body,0,2.08,0,.29,skin,[.85,1.08,.9]);
  const hair=sphere(body,0,2.25,.04,.27,mat(team==='home'?0x33231b:0x35231b),[.9,.45,.92]);
  // numbered shirt print
  const numCanvas=document.createElement('canvas');numCanvas.width=128;numCanvas.height=128;const ctx=numCanvas.getContext('2d');ctx.fillStyle='#fff';ctx.font='bold 76px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(number),64,66);
  const numberMesh=new THREE.Mesh(new THREE.PlaneGeometry(.35,.38),new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(numCanvas),transparent:true,side:THREE.DoubleSide}));numberMesh.position.set(0,1.45,.43);body.add(numberMesh);
  const limbs=[];for(const side of [-1,1]){
    const arm=new THREE.Group();arm.position.set(side*.52,1.68,0);body.add(arm);const armMesh=new THREE.Mesh(new THREE.CylinderGeometry(.13,.105,.68,9),shirt);armMesh.position.y=-.3;armMesh.rotation.z=side*-.15;arm.add(armMesh);sphere(arm,0,-.66,0,.11,skin);
    const leg=new THREE.Group();leg.position.set(side*.23,.53,0);g.add(leg);const thigh=new THREE.Mesh(new THREE.CylinderGeometry(.15,.13,.5,9),dark);thigh.position.y=-.25;leg.add(thigh);const shin=new THREE.Mesh(new THREE.CylinderGeometry(.105,.12,.43,9),skin);shin.position.set(0,-.66,0);leg.add(shin);const sock=new THREE.Mesh(new THREE.CylinderGeometry(.12,.115,.23,9),white);sock.position.set(0,-.67,0);leg.add(sock);const boot=new THREE.Mesh(new THREE.BoxGeometry(.23,.12,.38),mat(0x182019,.3));boot.position.set(0,-.82,-.1);leg.add(boot);limbs.push({arm,leg,side});
  }
  // Small soft shadow beneath each player.
  const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x07130d,transparent:true,opacity:.22,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.025;g.add(shadow);
  return {group:g,body,limbs,team,number,keeper,velocity:new THREE.Vector3(),homeX:x,homeZ:z,run:0,shirt};
}

