// Instanced crowd silhouettes keep the stadium lively without expensive draw calls.
const crowdColors=[0xe4c89e,0x3978a8,0xc85542,0xd5d4bd,0x5d9c67];
const crowdGeo=new THREE.SphereGeometry(.12,6,5);
for(let c=0;c<crowdColors.length;c++){
  const crowd=new THREE.InstancedMesh(crowdGeo,mat(crowdColors[c]),24);const dummy=new THREE.Object3D();
  for(let n=0;n<24;n++){dummy.position.set(x+side*(Math.random()*.55),y+.38+(Math.random()-.5)*.24,-50+(c*24+n)*.88);dummy.scale.set(.72,1.35,.72);dummy.updateMatrix();crowd.setMatrixAt(n,dummy.matrix);}
  crowd.instanceMatrix.needsUpdate=true;scene.add(crowd);
}

