const homePlayers=[makePlayer('home',0,25,7),makePlayer('home',-12,16,11),makePlayer('home',12,4,8),makePlayer('home',-16,-8,3),makePlayer('home',15,-19,10),makePlayer('home',0,44,1,true)];
const awayPlayers=[makePlayer('away',0,-22,9),makePlayer('away',-12,-15,6),makePlayer('away',12,-5,4),makePlayer('away',-15,8,2),makePlayer('away',15,18,5),makePlayer('away',0,-44,1,true)];
const captain=homePlayers[0], allPlayers=[...homePlayers,...awayPlayers];
const ballGroup=new THREE.Group();scene.add(ballGroup);
const ball=new THREE.Mesh(new THREE.SphereGeometry(.43,24,18),ballMat);ball.castShadow=true;ball.receiveShadow=true;ballGroup.add(ball);
const ballSeams=new THREE.Group();ballGroup.add(ballSeams);
for(let i=0;i<5;i++){const seam=new THREE.Mesh(new THREE.TorusGeometry(.24,.025,5,16),black);seam.rotation.set(i*.74,i*1.1,i*.38);ballSeams.add(seam);}
const ballShadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x06100a,transparent:true,opacity:.24,depthWrite:false}));ballShadow.rotation.x=-Math.PI/2;scene.add(ballShadow);
const ballState={position:new THREE.Vector3(0,.43,23.8),velocity:new THREE.Vector3(),owner:captain,air:0};
let facing=new THREE.Vector3(0,0,-1),stamina=100,homeScore=0,awayScore=0,matchSeconds=240,paused=false,goalLock=0,calloutTimer=0, soundOn=true, gameOver=false;
const keys={};
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape')togglePause();if(e.code==='KeyR')resetMatch();if(e.code==='Space'&&!e.repeat)shoot();if(e.code==='KeyE'&&!e.repeat)passBall();});
addEventListener('keyup',e=>keys[e.code]=false);
document.getElementById('pause-btn').onclick=togglePause;document.getElementById('resume-btn').onclick=togglePause;
document.getElementById('sound-btn').onclick=()=>{soundOn=!soundOn;document.getElementById('sound-btn').style.color=soundOn?'':'#f77';document.getElementById('sound-btn').textContent=soundOn?'♪':'×';};
function togglePause(){if(gameOver)return;paused=!paused;document.getElementById('pause-screen').classList.toggle('open',paused);}
function showEvent(title,subtitle,duration=2.2){document.getElementById('event-title').textContent=title;document.getElementById('event-sub').textContent=subtitle;document.getElementById('callout').classList.add('show');calloutTimer=duration;}
function shoot(){if(paused||gameOver||ballState.owner!==captain)return;ballState.owner=null;const power=keys.ShiftLeft||keys.ShiftRight?34:27;ballState.velocity.set(facing.x*power,keys.ShiftLeft||keys.ShiftRight?8:5.7,facing.z*power);ballState.position.copy(captain.group.position).addScaledVector(facing,1.05);ballState.position.y=.95;ballState.air=0;showEvent('STRIKE!','AIM FOR THE CORNERS',.8);}
function passBall(){if(paused||gameOver||ballState.owner!==captain)return;let target=null,best=Infinity;for(const p of homePlayers.slice(1,-1)){const d=captain.group.position.distanceTo(p.group.position);if(d<best){best=d;target=p;}}if(!target)return;const direction=target.group.position.clone().sub(captain.group.position).setY(0).normalize();ballState.owner=null;ballState.position.copy(captain.group.position).addScaledVector(direction,1);ballState.position.y=.75;ballState.velocity.set(direction.x*20,3.8,direction.z*20);ballState.air=0;showEvent('THREAD IT!','PASS COMPLETE',.8);}
function resetPositions(){
  homePlayers.forEach((p,i)=>{const positions=[[0,25],[-12,16],[12,4],[-16,-8],[15,-19],[0,44]][i];p.group.position.set(...[positions[0],0,positions[1]]);p.velocity.set(0,0,0);});
  awayPlayers.forEach((p,i)=>{const positions=[[0,-22],[-12,-15],[12,-5],[-15,8],[15,18],[0,-44]][i];p.group.position.set(positions[0],0,positions[1]);p.velocity.set(0,0,0);});
  captain.group.position.set(0,0,25);facing.set(0,0,-1);ballState.position.set(0,.43,23.8);ballState.velocity.set(0,0,0);ballState.owner=captain;ballState.air=0;goalLock=0;
}
function resetMatch(){homeScore=0;awayScore=0;matchSeconds=240;gameOver=false;paused=false;document.getElementById('pause-screen').classList.remove('open');document.getElementById('callout').classList.remove('show');document.getElementById('home-score').textContent='0';document.getElementById('away-score').textContent='0';resetPositions();}
function scoreGoal(team){if(goalLock>0)return;goalLock=2.4;if(team==='home'){homeScore++;showEvent('GOAL!','NORTHSIDE TAKES THE LEAD',2.2);}else{awayScore++;showEvent('GOAL!','THE RIVALS ARE BACK IN IT',2.2);}document.getElementById('home-score').textContent=homeScore;document.getElementById('away-score').textContent=awayScore;ballState.owner=null;ballState.velocity.set(0,0,0);}
function updateCaptain(dt){
  const move=new THREE.Vector3((keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),0,(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0));
  const sprint=(keys.ShiftLeft||keys.ShiftRight)&&move.lengthSq()>0&&stamina>0;const speed=sprint?11.8:7.6;
  if(move.lengthSq()>0){move.normalize();facing.lerp(move,.18).normalize();captain.group.position.addScaledVector(move,speed*dt);stamina=Math.max(0,stamina-(sprint?25:1.6)*dt);}else stamina=Math.min(100,stamina+11*dt);
  captain.group.position.x=THREE.MathUtils.clamp(captain.group.position.x,-32,32);captain.group.position.z=THREE.MathUtils.clamp(captain.group.position.z,-41,42);
  captain.group.rotation.y=Math.atan2(facing.x,facing.z)+Math.PI;
  document.getElementById('stamina-fill').style.width=`${stamina}%`;
}
function updateAI(dt,time){
  for(const p of allPlayers){if(p===captain)continue;const pos=p.group.position;let target=new THREE.Vector3(p.homeX,0,p.homeZ);let pace=3.0;
    if(p.team==='away'){
      if(ballState.owner===p){target.set(THREE.MathUtils.clamp(pos.x*.65,-8,8),0,Math.min(39,pos.z+20));pace=4.8;if(pos.z>25){const goalDir=new THREE.Vector3(-pos.x*.12,0,1).normalize();p.velocity.addScaledVector(goalDir,14*dt);}}
      else if(ballState.owner===captain||!ballState.owner){const dist=pos.distanceTo(ballState.position);if(dist<20||p.number===9||p.number===6){target.copy(ballState.position);target.y=0;pace=p.number===1?2.8:4.15;}}
      else if(ballState.owner.team==='home'){if(pos.distanceTo(ballState.owner.group.position)<14){target.copy(ballState.owner.group.position);target.y=0;pace=3.5;}}
    }else if(p!==captain){
      if(ballState.owner===captain){target.set(p.homeX*.72,0,p.homeZ<0?p.homeZ:Math.max(-28,p.homeZ-7));if(p.number===8)target.set(-10,0,captain.group.position.z-12);if(p.number===11)target.set(10,0,captain.group.position.z-8);}
      else if(ballState.owner===p){target.set(0,0,-40);pace=4.8;}
      else if(!ballState.owner&&pos.distanceTo(ballState.position)<9){target.copy(ballState.position);target.y=0;pace=4;}
    }
    const delta=target.sub(pos);delta.y=0;const dist=delta.length();if(dist>.6){delta.normalize();const accel=pace*dt*Math.min(1,dist/2);pos.addScaledVector(delta,accel);p.group.rotation.y=Math.atan2(delta.x,delta.z)+Math.PI;p.run=Math.min(1,p.run+dt*5);}else p.run=Math.max(0,p.run-dt*4);
    p.velocity.multiplyScalar(Math.max(0,1-dt*3));pos.addScaledVector(p.velocity,dt);pos.x=THREE.MathUtils.clamp(pos.x,-32,32);pos.z=THREE.MathUtils.clamp(pos.z,-43,43);
    for(const limb of p.limbs){limb.leg.rotation.x=Math.sin(time*10+(limb.side*1.5))*p.run*.65;limb.arm.rotation.x=-Math.sin(time*10+(limb.side*1.5))*p.run*.38;}
  }
  // Rival pressure can win the ball; the controlled forward can recover it nearby.
  if(ballState.owner===captain){for(const p of awayPlayers.slice(0,5)){if(p.group.position.distanceTo(captain.group.position)<1.25&&Math.random()<dt*.55){ballState.owner=p;showEvent('TACKLED!','WIN IT BACK',.9);break;}}}
  if(!ballState.owner){let closest=null,dist=2.05;for(const p of allPlayers){if(p.keeper)continue;const d=Math.hypot(p.group.position.x-ballState.position.x,p.group.position.z-ballState.position.z);if(d<dist&&ballState.position.y<1.35){closest=p;dist=d;}}if(closest&&ballState.velocity.length()<12){ballState.owner=closest;ballState.velocity.set(0,0,0);if(closest.team==='away')showEvent('THEY HAVE IT','PRESSURE THE BALL',.7);}}
  if(ballState.owner&&ballState.owner.team==='away'){
    const holder=ballState.owner;if(holder.group.position.z>28&&Math.random()<dt*.8){const aim=new THREE.Vector3(-holder.group.position.x*.08,0,1).normalize();ballState.owner=null;ballState.position.copy(holder.group.position);ballState.position.y=1;ballState.velocity.set(aim.x*25,5,aim.z*25);}
  }
}

function updateBall(dt,time){
  const owner=ballState.owner;
  if(owner){const dir=owner===captain?facing:new THREE.Vector3(Math.sin(owner.group.rotation.y),0,-Math.cos(owner.group.rotation.y));const ahead=owner===captain?.86:.72;ballState.position.set(owner.group.position.x+dir.x*ahead,.43,owner.group.position.z+dir.z*ahead);ballState.velocity.set(0,0,0);}
  else{
    ballState.velocity.y-=17*dt;ballState.position.addScaledVector(ballState.velocity,dt);
    if(ballState.position.y<.43){ballState.position.y=.43;if(ballState.velocity.y< -1.2)ballState.velocity.y*=-.42;else ballState.velocity.y=0;}
    ballState.velocity.x*=Math.pow(.985,dt*60);ballState.velocity.z*=Math.pow(.985,dt*60);
    if(ballState.position.y<=.46){ballState.velocity.x*=Math.pow(.965,dt*60);ballState.velocity.z*=Math.pow(.965,dt*60);}
    if(Math.abs(ballState.position.x)>34.2){ballState.position.x=Math.sign(ballState.position.x)*34.2;ballState.velocity.x*=-.6;}
    if(ballState.position.z < -49.5){if(Math.abs(ballState.position.x)<4.4&&ballState.position.y<2.55)scoreGoal('home');else{ballState.position.z=-49.5;ballState.velocity.z=Math.abs(ballState.velocity.z)*.55;}}
